package khoa.tools.client.feature.itemcounter;
import java.util.*;
import com.mojang.brigadier.builder.LiteralArgumentBuilder;
import net.fabricmc.fabric.api.client.command.v2.*;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.client.*; import net.minecraft.client.gui.GuiGraphicsExtractor; import net.minecraft.client.gui.components.*; import net.minecraft.client.gui.screens.Screen; import net.minecraft.client.input.MouseButtonEvent; import net.minecraft.commands.CommandBuildContext; import net.minecraft.network.chat.Component; import net.minecraft.world.item.ItemStack;
import khoa.tools.client.feature.KhoaFeature;
public final class ItemCounterFeature implements KhoaFeature {
 private static boolean on; private static long started,elapsed; private static final Map<String,Integer> start=new LinkedHashMap<>(),now=new LinkedHashMap<>(),result=new LinkedHashMap<>();
 public String id(){return "itemcounter";} public String displayName(){return "Item Counter";} public String description(){return "Counts item gains and opens a scrollable report with item/s, item/m and item/h tabs.";} public boolean isActive(){return on;}
 public void activate(Minecraft mc){if(!on){on=true;started=System.currentTimeMillis();start.clear();now.clear();result.clear();snapshot(mc,start);}else{snapshot(mc,now);elapsed=Math.max(1000,System.currentTimeMillis()-started);result.clear();for(var e:now.entrySet())result.put(e.getKey(),Math.max(0,e.getValue()-start.getOrDefault(e.getKey(),0)));on=false;mc.setScreen(new ReportScreen());}KhoaFeature.say(mc,"Item Counter: "+(on?"on (list reset)":"off (report saved)"));}
 public void onInit(){ClientTickEvents.END_CLIENT_TICK.register(mc->{if(on&&mc.player!=null){snapshot(mc,now);if(started==0&&!now.equals(start))started=System.currentTimeMillis();}});}
 private static void snapshot(Minecraft mc,Map<String,Integer> out){out.clear();for(int i=0;i<mc.player.getInventory().getContainerSize();i++){ItemStack s=mc.player.getInventory().getItem(i);if(!s.isEmpty())out.merge(s.getHoverName().getString(),s.getCount(),Integer::sum);}}
 public void registerCommands(LiteralArgumentBuilder<FabricClientCommandSource> root,CommandBuildContext c){root.then(ClientCommands.literal(id()).executes(x->{activate(x.getSource().getClient());return 1;}).then(ClientCommands.literal("gui").executes(x->{x.getSource().getClient().setScreen(new ReportScreen());return 1;})));}
 private static long seconds(){return Math.max(1,elapsed/1000);}
 private static final class ReportScreen extends Screen {int tab; ReportList list; ReportScreen(){super(Component.literal("Item Counter Report"));} protected void init(){clearWidgets();int w=Math.min(500,width-30),x=(width-w)/2;for(int i=0;i<3;i++){final int t=i;addRenderableWidget(Button.builder(Component.literal(i==0?"Item / second":i==1?"Item / minute":"Item / hour"),b->{tab=t;rebuildWidgets();}).bounds(x+i*w/3,28,w/3-4,20).build());}list=new ReportList(minecraft,w,height-110,56,18);list.setX(x);for(var e:result.entrySet())list.add(e.getKey(),rate(e.getValue()));addRenderableWidget(list);addRenderableWidget(Button.builder(Component.literal("Close"),b->onClose()).bounds(width/2-40,height-35,80,20).build());}double rate(int n){double s=seconds();return tab==0?n/s:tab==1?n*60.0/s:n*3600.0/s;}public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float pt){super.extractRenderState(g,mx,my,pt);g.centeredText(font,title,width/2,10,0xFFFFFFFF);g.centeredText(font,"Collected during "+seconds()+" seconds",width/2,20,0xFFAAAAAA);}final class ReportList extends ObjectSelectionList<Row>{ReportList(Minecraft m,int w,int h,int y,int rh){super(m,w,h,y,rh);}void add(String n,double v){addEntry(new Row(n,v));}}final class Row extends ObjectSelectionList.Entry<Row>{String n;double v;Row(String n,double v){this.n=n;this.v=v;}public Component getNarration(){return Component.literal(n);}public void extractContent(GuiGraphicsExtractor g,int mx,int my,boolean h,float pt){g.text(ReportScreen.this.font,n+"  "+String.format(Locale.ROOT,"%.2f",v),getContentX()+5,getContentYMiddle()-4,0xFFFFFFFF);}public boolean mouseClicked(MouseButtonEvent e,boolean d){return true;}}}
}
